def join_tuples(tuples):
    """
    Join tuples if they have similar initial elements.
    """
    tuples = sorted(tuples, key=lambda t: t[0])
    for i in range(1, len(tuples)):
        if tuples[i][0] == tuples[i-1][0]:
            tuples[i-1] = tuples[i-1] + tuples[i]
            del tuples[i]
    return tuples

def find_two_numbers(range_start, range_end):
    for i in range(range_start, range_end):
        for j in range(range_start, range_end):
            if i!= j:
                lcm = i * j // gcd(i, j)
                if lcm >= range_start and lcm <= range_end:
                    return i, j

