def sum_odd_factors(n):
    sum = 0
    for i in range(1, int(n ** 0.5) + 1):
        if n % i == 0 and i % 2 == 1:
            sum += i
    return sum

def sum_of_odd_factors(n):
    """
    Returns the sum of all odd factors of n.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 0
    if n == 1:
        return 1
    if n % 2 == 0:
        return sum_of_odd_factors(n // 2)
    return n + sum_of_odd_factors(n - 1)

def find_kth_element(arr1, arr2, k):
    i, j = 0, 0
    result = []

    while i < len(arr1) and j < len(arr2):
        if arr1[i] < arr2[j]:
            result.append(arr1[i])
            i += 1
        else:
            result.append(arr2[j])
            j += 1

    while len(result) < k:
        result.append(arr1[i])
        i += 1

    while len(result) > k:
        result.pop()

    return result[k-1]

