def max_average_path(matrix):
    if not matrix:
        return 0
    if len(matrix) == 1:
        return matrix[0][0]
    max_sum = 0
    for i in range(len(matrix)):
        for j in range(len(matrix[0])):
            if i == 0 or j == 0:
                matrix[i][j] = matrix[i][j] + max(matrix[i-1][j], matrix[i][j-1])
            else:
                matrix[i][j] = matrix[i][j] + max(matrix[i-1][j], matrix[i][j-1], matrix[i-1][j-1])
            max_sum = max(max_sum, matrix[i][j])
    return max_sum

