def sort_by_length_and_value(lst):
    """
    Sort a list of lists by length and value.
    """
    def sort_by_length(lst):
        """
        Sort a list of lists by length.
        """
        return sorted(lst, key=lambda x: len(x))

    def sort_by_value(lst):
        """
        Sort a list of lists by value.
        """
        return sorted(lst, key=lambda x: x[0])

    return sort_by_length(sort_by_value(lst))

def count_inversions(arr):
    """
    Returns the number of inversions in the given array.

    An inversion is a pair of elements (a, b) such that a > b and a < b.
    """
    n = len(arr)
    count = 0
    for i in range(n-1):
        for j in range(i+1, n):
            if arr[i] > arr[j]:
                count += 1
    return count

def roman_to_int(roman):
    roman_dict = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    result = 0
    prev_value = 0
    for char in roman:
        current_value = roman_dict[char]
        if current_value > prev_value:
            result += current_value - 2 * prev_value
        else:
            result += current_value
        prev_value = current_value
    return result

def find_min_element(arr):
    start, end = 0, len(arr) - 1
    while start < end:
        mid = (start + end) // 2
        if mid == 0 or arr[mid] < arr[mid - 1]:
            return arr[mid]
        end = mid
    return arr[start]

def frequency_count(lst):
    """
    Return a dictionary with the frequency count of each element in lst.
    """
    d = {}
    for item in lst:
        if item not in d:
            d[item] = 1
        else:
            d[item] += 1
    return d

