def pell(n):
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return pell(n-1) + pell(n-2)

def avg_odds(n):
    sum = 0
    i = 1
    while i <= n:
        sum += i
        i += 2
    return sum / (i - 1)

def even_odd_sum(n):
    even_sum = 0
    odd_sum = 0
    for i in str(n):
        if int(i) % 2 == 0:
            even_sum += int(i)
        else:
            odd_sum += int(i)
    return even_sum - odd_sum

def count_characters(string):
    count = {}
    for char in string:
        if char.isupper():
            count[char] = count.get(char, 0) + 1
        else:
            count[char.lower()] = count.get(char.lower(), 0) + 1
    return count

